document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',()=>{document.body.classList.remove('menu-open')})); 
const reels=[['حلاوة الكيمياء في بساطتها','شرح سريع يخليك تشوف المعلومة بشكل مختلف'],['افهمها مش تحفظها','فكرة كيمياء في دقيقة واحدة'],['سؤال اليوم مع الغزالي','اختبر فهمك قبل ما تكمل مذاكرة'],['نصيحة تفرق معاك','خطوة صغيرة تقرّبك من الدرجة النهائية']];const reelUrls=['https://www.facebook.com/reel/1900454814030820/','https://www.facebook.com/reel/1955985251532728/','https://www.facebook.com/reel/1088108914077452/','https://www.facebook.com/reel/1128655579635361/'];const reelsSection=document.createElement('section');reelsSection.id='reels';reelsSection.className='section reels';reelsSection.innerHTML='<div class="section-heading"><div><p class="eyebrow">من شرح المستر</p><h2>شوف الكيمياء<br><em>بطريقة مختلفة.</em></h2></div><p>أربع لقطات سريعة من محتوى الأستاذ إسلام الغزالي — افهم، طبّق، وكمّل.</p></div><div class="reels-grid">'+reels.map((item,i)=>'<article class="reel-card"><a href="'+reelUrls[i]+'" target="_blank" rel="noreferrer"><div class="reel-cover" style="background-image:linear-gradient(180deg,#071c2b00 35%,#071c2bcc),url(reel-'+(i+1)+'.jpg)"><span class="reel-play">▶</span><span class="reel-number">0'+(i+1)+'</span></div><div class="reel-info"><b>'+item[0]+'</b><small>'+item[1]+'</small><span>شاهد الريل ↗</span></div></a></article>').join('')+'</div>';document.querySelector('#social').before(reelsSection);document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="#reels">الريلز</a>');
